method(expr_name, PowCone3D) <- function(x) {
  sprintf("PowCone3D(%s, %s, %s; %s)",
    expr_name(x@.x), expr_name(x@.y), expr_name(x@.z), expr_name(x@alpha))
}

# -- is_dcp -------------------------------------------------------
## CVXPY SOURCE: power.py lines 112-118
## Under the DPP scope CVXPY also requires `exps_ok`: the exponent alpha must not
## be a Parameter (power.py:116). Ported 1.9.2.9136 (claims-audit row C0345; the
## deferral in ADR D4.6 is closed).

method(is_dcp, PowCone3D) <- function(x) {
  args_ok <- .all_args(x, is_affine)
  if (dpp_scope_active()) {
    exps_ok <- !.s7_is(x@alpha, Parameter)
    return(args_ok && exps_ok)
  }
  args_ok
}

