# -- residual -----------------------------------------------------
## CVXPY SOURCE: power.py lines 78-91
## TODO: projection should be implemented directly

method(residual, PowCone3D) <- function(x) {
  xv <- value(x@.x)
  yv <- value(x@.y)
  zv <- value(x@.z)
  if (is.null(xv) || is.null(yv) || is.null(zv)) return(NULL)

  alpha_val <- as.numeric(value(x@alpha))
  xv <- as.numeric(xv)
  yv <- as.numeric(yv)
  zv <- as.numeric(zv)

  ## Feasibility: x^alpha * y^(1-alpha) >= |z|, x >= 0, y >= 0
  n <- length(xv)
  resid <- numeric(n)
  for (i in seq_len(n)) {
    if (xv[i] >= 0 && yv[i] >= 0) {
      lhs <- xv[i]^alpha_val[i] * yv[i]^(1 - alpha_val[i])
      resid[i] <- max(0, abs(zv[i]) - lhs)
    } else {
      resid[i] <- abs(min(0, xv[i])) + abs(min(0, yv[i])) + abs(zv[i])
    }
  }
  if (n == 1L) resid[1L] else resid
}

# -- save_dual_value ----------------------------------------------
## CVXPY SOURCE: power.py lines 132-139
##
## `val` arrives as the (3, num_cones) matrix that ConeMatrixStuffing.invert
## produced by reshaping the flat dual to this constraint's shape -- PowCone3D
## is deliberately NOT on that method's exempt list, exactly as upstream
## (cone_matrix_stuffing.py:499-503).  Row i is coordinate i across all cones.
##
## This method used to build that matrix itself, because CVXR had no reshape in
## the stuffing layer: the dual arrived FLAT and INTERLEAVED per cone
## (x1,y1,z1, x2,y2,z2, ...), since format_constraints stuffs PowCone3D with
## spacing = 2, offset = i - 1 (conic_solver.R:158-172).  Filling that table
## `byrow` transposes it -- silently wrong for every constraint with
## num_cones() >= 2, invisible at nc = 1 where both fills coincide (2c16fca).
## With the reshape ported (D_19.6 step C) the layout knowledge lives in ONE
## place; keeping a local copy here would relocate the deviation, not remove it.

method(save_dual_value, PowCone3D) <- function(x, val) {
  ## CVXPY SOURCE: power.py:132-139 -- dv_i = reshape(value[i], arg_i.shape, 'F')
  val_mat <- as.matrix(val)
  dv0 <- matrix(val_mat[1L, ], nrow = x@.x@shape[1L], ncol = x@.x@shape[2L])
  dv1 <- matrix(val_mat[2L, ], nrow = x@.y@shape[1L], ncol = x@.y@shape[2L])
  dv2 <- matrix(val_mat[3L, ], nrow = x@.z@shape[1L], ncol = x@.z@shape[2L])
  value(x@dual_variables[[1L]]) <- dv0
  value(x@dual_variables[[2L]]) <- dv1
  value(x@dual_variables[[3L]]) <- dv2
  invisible(x)
}

# -- dual_cone ----------------------------------------------------
## CVXPY SOURCE: power.py lines 141-155
## dual = PowCone3D(x/alpha, y/(1-alpha), z, alpha); explicit args are checked
## for count and shape (power.py:149-153) by .dual_cone_check_args (cones.R).

method(dual_cone, PowCone3D) <- function(x, ...) {
  args <- list(...)
  if (length(args) == 0L) {
    PowCone3D(x@dual_variables[[1L]] / x@alpha,
              x@dual_variables[[2L]] / (1 - x@alpha),
              x@dual_variables[[3L]],
              x@alpha)
  } else {
    .dual_cone_check_args(x, args)
    PowCone3D(args[[1L]] / x@alpha,
              args[[2L]] / (1 - x@alpha),
              args[[3L]],
              x@alpha)
  }
}

