# -- residual -----------------------------------------------------
## CVXPY SOURCE: power.py lines 258-271
## TODO: projection should be implemented directly

method(residual, PowConeND) <- function(x) {
  W_val <- value(x@.W)
  z_val <- value(x@.z)
  if (is.null(W_val) || is.null(z_val)) return(NULL)

  alpha_val <- as.matrix(value(x@alpha))
  W_val <- as.matrix(W_val)
  z_val <- as.numeric(z_val)

  ## Transpose if axis == 1 to normalize to column-wise
  if (x@axis == 1L) {
    W_val <- t(W_val)
    alpha_val <- t(alpha_val)
  }

  n_cones <- length(z_val)
  resid <- numeric(n_cones)
  for (j in seq_len(n_cones)) {
    w_col <- W_val[, j]
    a_col <- alpha_val[, j]
    if (all(w_col >= 0)) {
      lhs <- prod(w_col^a_col)
      resid[j] <- max(0, abs(z_val[j]) - lhs)
    } else {
      resid[j] <- sum(abs(pmin(0, w_col))) + abs(z_val[j])
    }
  }
  if (n_cones == 1L) resid[1L] else resid
}

# -- save_dual_value ----------------------------------------------
## CVXPY SOURCE: power.py lines 301-314
## Value has shape (m+1, k); first m rows are W duals, last row is z duals.
## ConeMatrixStuffing.invert delivers it already shaped (PowConeND is not on its
## exempt list), so the old `if (!is.matrix(val))` fallback -- which existed only
## because CVXR had no reshape there -- is gone (D_19.6 step C).

method(save_dual_value, PowConeND) <- function(x, val) {
  val <- as.matrix(val)
  dW <- val[seq_len(nrow(val) - 1L), , drop = FALSE]
  dz <- val[nrow(val), ]

  if (x@axis == 1L) dW <- t(dW)

  ## Drop trailing dimension if single column
  if (ncol(dW) == 1L) dW <- as.numeric(dW)

  ## CVXPY saves the 1-D dz into z, whatever z's orientation; in R give it
  ## z's shape explicitly, or a 1 x k z rejects a plain length-k vector.
  z_shape <- x@dual_variables[[2L]]@shape
  value(x@dual_variables[[1L]]) <- dW
  value(x@dual_variables[[2L]]) <- matrix(dz, nrow = z_shape[1L], ncol = z_shape[2L])
  invisible(x)
}

# -- dual_cone ----------------------------------------------------
## CVXPY SOURCE: power.py lines 316-329
## dual = PowConeND(W/alpha, z, alpha, axis); explicit args are checked for
## count and shape (power.py:326-327) by .dual_cone_check_args (cones.R), and
## the value of the first must have alpha's value shape (power.py:328).

method(dual_cone, PowConeND) <- function(x, ...) {
  args <- list(...)
  if (length(args) == 0L) {
    PowConeND(x@dual_variables[[1L]] / x@alpha,
              x@dual_variables[[2L]],
              x@alpha, axis = x@axis)
  } else {
    .dual_cone_check_args(x, args)
    w_val <- value(args[[1L]])
    a_val <- value(x@alpha)
    if (is.null(w_val) || is.null(a_val) ||
        !identical(dim(as.matrix(w_val)), dim(as.matrix(a_val)))) {
      cli_abort(
        "{.fn dual_cone}: the value of the first argument must have the shape of alpha's value."
      )
    }
    PowConeND(args[[1L]] / x@alpha,
              args[[2L]],
              x@alpha, axis = x@axis)
  }
}

